import React, { useState, useEffect } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './PendingUsers.css';

const PendingUsers = () => {
  // ✅ CRITICAL: Initialize as empty array, not null/undefined
  const [pendingUsers, setPendingUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    fetchPendingUsers();
  }, []);

  const fetchPendingUsers = async () => {
    setIsLoading(true);
    setError('');

    try {
      const result = await apiCall(adminAPI.getPendingUsers);

      if (result.success) {
        // ✅ CRITICAL: Ensure we always set an array
        const users = result.data;
        
        // Handle different API response structures
        if (Array.isArray(users)) {
          setPendingUsers(users);
        } else if (users && Array.isArray(users.users)) {
          // In case API returns { users: [...] }
          setPendingUsers(users.users);
        } else if (users && Array.isArray(users.data)) {
          // In case API returns { data: [...] }
          setPendingUsers(users.data);
        } else {
          // If no valid array found, set empty array
          console.warn('API response is not an array:', users);
          setPendingUsers([]);
        }
      } else {
        setError(result.error || 'Failed to fetch pending users');
        setPendingUsers([]); // ✅ Set empty array on error
      }
    } catch (err) {
      console.error('Error fetching pending users:', err);
      setError('An unexpected error occurred');
      setPendingUsers([]); // ✅ Set empty array on exception
    }

    setIsLoading(false);
  };

  const handleUserAction = async (userId, action) => {
    setError('');
    setSuccess('');

    try {
      const result = await apiCall(adminAPI.updateUserStatus, {
        userId,
        action
      });

      if (result.success) {
        setSuccess(`User ${action.toLowerCase()} successfully!`);
        fetchPendingUsers(); // Refresh the list
      } else {
        setError(result.error || `Failed to ${action.toLowerCase()} user`);
      }
    } catch (err) {
      console.error('Error updating user status:', err);
      setError('An unexpected error occurred');
    }
  };

  // ✅ Add debugging - remove in production
  console.log('pendingUsers type:', typeof pendingUsers, 'isArray:', Array.isArray(pendingUsers), 'value:', pendingUsers);

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading pending users...
      </div>
    );
  }

  return (
    <div className="pending-users">
      <div className="page-header">
        <div className="container">
          <h1>Pending User Approvals</h1>
          <p>Review and approve new user registrations</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        {success && (
          <div className="alert alert-success">
            {success}
          </div>
        )}

        {/* ✅ SAFE: Always check if array before using .length */}
        <div className="users-summary">
          <h2>Pending Approvals ({Array.isArray(pendingUsers) ? pendingUsers.length : 0})</h2>
        </div>

        {/* ✅ SAFE: Multiple safety checks */}
        {!Array.isArray(pendingUsers) || pendingUsers.length === 0 ? (
          <div className="no-users">
            <div className="no-users-icon">👥</div>
            <h3>No Pending Users</h3>
            <p>
              {!Array.isArray(pendingUsers) 
                ? "There was an error loading user data."
                : "All user registrations have been processed."
              }
            </p>
            {!Array.isArray(pendingUsers) && (
              <button onClick={fetchPendingUsers} className="btn btn-primary">
                Retry Loading
              </button>
            )}
          </div>
        ) : (
          <div className="users-list">
            {/* ✅ SAFE: Now we know pendingUsers is definitely an array */}
            {pendingUsers.map(user => (
              <UserCard
                key={user.id || user._id} // Handle different ID formats
                user={user}
                onAction={handleUserAction}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const UserCard = ({ user, onAction }) => {
  const [isProcessing, setIsProcessing] = useState(false);

  const handleAction = async (action) => {
    setIsProcessing(true);
    await onAction(user.id || user._id, action);
    setIsProcessing(false);
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not available';
    try {
      return new Date(dateString).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (err) {
      return 'Invalid date';
    }
  };

  return (
    <div className="user-card">
      <div className="user-header">
        <div className="user-info">
          <h3>{user.name || user.fullName || 'Unknown User'}</h3>
          <p className="user-email">{user.email || 'No email provided'}</p>
        </div>
        <div className="user-actions">
          <button
            onClick={() => handleAction('APPROVED')}
            className="btn btn-success btn-sm"
            disabled={isProcessing}
          >
            {isProcessing ? 'Processing...' : 'Approve'}
          </button>
          <button
            onClick={() => handleAction('REJECTED')}
            className="btn btn-danger btn-sm"
            disabled={isProcessing}
          >
            {isProcessing ? 'Processing...' : 'Reject'}
          </button>
        </div>
      </div>

      <div className="user-details">
        <div className="detail-grid">
          <div className="detail-item">
            <span className="detail-label">Role:</span>
            <span className="detail-value">{user.role || 'Not specified'}</span>
          </div>
          
          <div className="detail-item">
            <span className="detail-label">Registered:</span>
            <span className="detail-value">{formatDate(user.createdAt || user.registeredAt)}</span>
          </div>

          {user.contactNumber && (
            <div className="detail-item">
              <span className="detail-label">Contact:</span>
              <span className="detail-value">{user.contactNumber}</span>
            </div>
          )}

          {user.location && (
            <div className="detail-item">
              <span className="detail-label">Location:</span>
              <span className="detail-value">{user.location}</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PendingUsers;

// ✅ Alternative safer approach using custom hook
export const useSafeArray = (initialValue = []) => {
  const [data, setData] = useState(initialValue);
  
  const setSafeData = (newData) => {
    if (Array.isArray(newData)) {
      setData(newData);
    } else if (newData && typeof newData === 'object') {
      // Try to extract array from object
      const possibleArrays = ['data', 'users', 'items', 'results'];
      const foundArray = possibleArrays.find(key => Array.isArray(newData[key]));
      
      if (foundArray) {
        setData(newData[foundArray]);
      } else {
        console.warn('Could not find array in response:', newData);
        setData([]);
      }
    } else {
      console.warn('Setting non-array data:', newData);
      setData([]);
    }
  };
  
  return [data, setSafeData];
};
